/// The combined HEAD→worktree diff for a file that has BOTH a `.index` delta (HEAD→index) and a
/// `.workingTree` delta (index→worktree) — i.e. staged, then edited again. `indexDelta.oldFile.id`
/// is the file's blob at HEAD (empty/invalid, and so `nil` after `show`, when the file is new since
/// HEAD — same "no old side" case `gitFormat` already renders as `/dev/null`); the new side always
/// comes from the CURRENT on-disk content, never the staged blob, so both legs of the edit show up
/// as one diff. Mirrors `workingPatch`'s `.conflicted` case, which reads HEAD→worktree the same way.
private static func combinedWorkingDiff(
  _ repo: Repository, indexDelta: Diff.Delta, root: URL
) throws -> String {
  let headBlob: Blob? = try? repo.show(id: indexDelta.oldFile.id)
  let oldPath = indexDelta.oldFile.path.isEmpty ? indexDelta.newFile.path : indexDelta.oldFile.path
  guard indexDelta.type != .deleted else {
    // The worktree half can't itself be `.deleted` while an `.index` delta also exists (deleting a
    // staged addition just unstages it) — but the STAGED half can be a deletion later re-added to,
    // which `Self.workingPatch`'s existing per-delta path already renders correctly. Nothing to
    // combine here.
    return ""
  }
  let patch = try repo.patch(from: headBlob, to: root.appendingPathComponent(oldPath))
  return Self.gitFormat(
    patch, oldPath: oldPath, newPath: oldPath, type: headBlob == nil ? .added : indexDelta.type)
}

