  /// REGRESSION: a slot showing author A raises a fetch; before it resolves, the SAME slot is
  /// reused for author B (SwiftUI cancels A's `.task`, but `AvatarImageLoader.load` neither checks
  /// nor propagates that cancellation — its `fetch` keeps running on an unstructured `Task` with no
  /// link back to the view's). If `AvatarView` ever stops checking `Task.isCancelled` before
  /// committing the result, A's stale image lands in `result` after B has already taken over the
  /// slot — the wrong person's avatar. `AvatarView.lastCommittedResult` (debug-only) is the seam:
  /// this test hosts exactly one `AvatarView` at a time, so it unambiguously reports the last value
  /// any `.task` actually committed.
  @MainActor
  func testStaleInFlightFetchNeverOverwritesANewerSubjectInTheSameSlot() throws {
    let emailA = "author-a@example.com"
    let emailB = "author-b@example.com"
    let urlA = gravatarURL(email: emailA)
    let urlB = gravatarURL(email: emailB)
    StubURLProtocol.registry.setResponse(status: 200, data: try pngData(.red), for: urlA)
    StubURLProtocol.registry.setResponse(status: 200, data: try pngData(.blue), for: urlB)
    StubURLProtocol.registry.gate(urlA)  // hold A's response until this test releases it

    let loader = AvatarImageLoader(session: makeSession())
    let controller = SubjectController(
      AvatarSubject(author: VCSAuthor(name: "A", email: emailA), pixelSize: 16))
    let (window, view) = host(controller, loader: loader)
    defer { window.close() }

    // Let A's `.task` start and actually reach the gated request (not just get scheduled).
    settle(view, until: { StubURLProtocol.registry.callCount(for: urlA) > 0 })
    XCTAssertGreaterThan(
      StubURLProtocol.registry.callCount(for: urlA), 0,
      "fixture must actually reach A's request before swapping the subject")

    // Same slot, different person — SwiftUI cancels A's `.task` (taskKey changes) and starts B's.
    controller.subject = AvatarSubject(author: VCSAuthor(name: "B", email: emailB), pixelSize: 16)
    settle(view, until: { StubURLProtocol.registry.callCount(for: urlB) > 0 })
    settle(view, until: { AvatarView.lastCommittedResult != nil })
    XCTAssertEqual(
      AvatarView.lastCommittedResult, .image(try pngImage(.blue)),
      "B's own fetch must land before A's stale one arrives, to set up the real race below")

    // NOW let A's held-open response land, well after B has already committed its own result.
    StubURLProtocol.registry.release(urlA)
    settle(view, seconds: 0.5)

    XCTAssertEqual(
      AvatarView.lastCommittedResult, .image(try pngImage(.blue)),
      "A's late-arriving, stale fetch must never overwrite B's already-committed result")
  }

  /// Decodes the SAME bytes `pngData` would have produced, for an `Equatable` comparison against
  /// `AvatarImageLoader.LoadResult` (which wraps `NSImage`, not raw bytes) — two separately-decoded
  /// `NSImage`s from identical PNG bytes compare equal via `NSImage.isEqual`.
  private func pngImage(_ color: NSColor) throws -> NSImage {
    try XCTUnwrap(NSImage(data: try pngData(color)))
  }
}

